def c6_saar(r):
    words = r.choice([40, 50, 60])
    focus = cp('c6_saar', r, ['कहानी का सार', 'कहानी का सार ज़मींदार के दृष्टिकोण से (मैं-शैली में)', 'कहानी का सार विधवा के दृष्टिकोण से (मैं-शैली में)',
                              'कहानी का सार अपने छोटे भाई-बहन को सुनाने के लिए सरल भाषा में', 'कहानी का सार इस प्रकार कि अंत में उसकी सीख भी आ जाए'])
    return {'stem': f'"एक टोकरी भर मिट्टी"—{focus} लगभग {words} शब्दों में लिखिए।',
            'answer': 'ज़मींदार महल का अहाता बढ़ाने के लिए विधवा की झोंपड़ी चाहता है; वह यादों के कारण मना करती है; ज़मींदार अदालत से कब्ज़ा कर लेता है; '
                      'पोती की ख़ातिर विधवा एक टोकरी मिट्टी ले जाना चाहती है और उसे उठवाने को कहती है; ज़मींदार उसे उठा नहीं पाता; विधवा के प्रश्न से उसका हृदय बदलता है और वह झोंपड़ी लौटा देता है।',
            'key': 'अंक-विभाजन (3): घटनाओं का सही क्रम 2, संक्षिप्त और स्पष्ट भाषा 1।'}


def c6_seq(r):
    ev = ['ज़मींदार का महल का अहाता बढ़ाने की इच्छा करना', 'विधवा का झोंपड़ी छोड़ने से मना करना', 'अदालत से ज़मींदार का कब्ज़ा होना',
          'विधवा का टोकरी भर मिट्टी माँगने आना', 'ज़मींदार का टोकरी न उठा पाना', 'ज़मींदार का झोंपड़ी लौटा देना']
    i = sorted(r.sample(range(6), 4))
    pick = [ev[x] for x in i]
    sh = pick[:]
    while sh == pick:
        r.shuffle(sh)
    return {'stem': '"एक टोकरी भर मिट्टी" कहानी की इन घटनाओं को सही क्रम में लिखिए: ' + '; '.join(f'({k + 1}) {e}' for k, e in enumerate(sh)),
            'answer': ' → '.join(pick), 'key': 'सही क्रम 1 अंक।'}


