C9_ORDER = ['कमरा', 'घर', 'मोहल्ला', 'नगर', 'देश', 'पृथ्वी', 'सौर मंडल', 'आकाशगंगा', 'ब्रह्मांड']


def c9_order(r):
    i = sorted(r.sample(range(len(C9_ORDER)), 4))
    pick = [C9_ORDER[x] for x in i]
    sh = pick[:]
    while sh == pick:
        r.shuffle(sh)
    return {'stem': 'कविता के भाव के अनुसार इन्हें छोटे से बड़े के क्रम में लिखिए: ' + ', '.join(sh), 'answer': ' → '.join(pick),
            'key': 'सही क्रम 1 अंक (हर इकाई अगली के भीतर समाई है)।'}


def c9_bigger(r):
    i, j = sorted(r.sample(range(len(C9_ORDER)), 2))
    small, big = C9_ORDER[i], C9_ORDER[j]
    others = r.sample([x for k, x in enumerate(C9_ORDER) if k < j and x != small], min(3, j - 1)) if j >= 4 else None
    if not others or len(others) < 3:
        raise ValueError('too few')
    return mcq(f'कविता में बताए गए विस्तार के क्रम में इनमें से सबसे बड़ा कौन है?', big, others, f'क्रम: {" → ".join(C9_ORDER)}।', r)


